/* ===== src/js/61-sheet.js ===== */
/* ==========================================================================
   SG.sheet: the parts of a bottom sheet that CSS cannot do
   --------------------------------------------------------------------------
   Opening, closing, the scrim tap, Esc on a modal sheet and focus return are the
   native <dialog> plus src/js/60-dialog.js (load order: this file needs it). This file adds:

   - THE HANDLE      [data-sg-sheet-size] is a real <button aria-pressed> with a stable label.
                     Click / Enter / Space toggles data-size="half" | "full" on its sheet and
                     keeps aria-pressed in step. ArrowUp sets full, ArrowDown sets half (the
                     window-splitter keys), so a keyboard user never needs the drag.
   - DRAG            a pointer enhancement on the handle and the bar. Drag down past 30% of the
                     height, or flick, and it closes as if Esc was pressed (so `cancel` can veto,
                     and data-required disables it). Drag up and it goes to full height. Every
                     drag has a button: the handle, Close, Esc, the scrim. WCAG 2.5.7.
                     A drag that actually moved swallows the click that follows, so letting go
                     over the handle does not also toggle it.
   - Esc on a NON-MODAL sheet (<section class="sheet card" popover="manual">). The browser does
     not close a manual popover on Esc. Only while focus is inside it, so the page behind keeps
     its own Esc.
   - focus return and scroll-region fix-up for non-modal sheets (toggle event)
   - FOCUS NOT OBSCURED (WCAG 2.4.11) for a persistent panel: it covers part of a page that stays
     usable, so while it is open its size is written to --sg-sheet-block / --sg-sheet-inline on
     <html> and sheet.css turns that into scroll-padding, the same way the dock and app bar keep
     a focused control clear of themselves.

   - THE ACTION ROW  .sheet__actions is one right-aligned row while every pill fits on it, else a stack
                     of full-width pills (SG.fit writes data-fit="row" | "stack"; sheet.css draws both).
                     It is measured again when the sheet opens, turns or the reader's text size changes.

   There is no drag in the side-panel layout (48em and up): sheet.css sets --_side to 1 there
   and this file reads it, so CSS and JS cannot disagree about which layout is showing.

   Motion: while dragging the sheet follows the finger exactly (direct manipulation is allowed
   under reduced motion). Releasing to dismiss slides out, or fades if SG.motion.reduced().
   ========================================================================== */
(function (SG) {
  'use strict';

  var SLOP = 6;             // px before a press becomes a drag (taps must stay taps)
  var CLOSE_FRACTION = 0.3; // of the sheet height
  var FLICK = 0.5;          // px/ms downward
  var EXPAND_DRAG = 60;     // px upward

  function popoverOpen(el) {
    try { return el.matches(':popover-open'); } catch (e) { return false; }
  }
  function isOpen(sheet) {
    return sheet.tagName === 'DIALOG' ? sheet.open : popoverOpen(sheet);
  }
  function isPanel(sheet) {
    return getComputedStyle(sheet).getPropertyValue('--_side').trim() === '1';
  }

  /* ---- The action row: one row, or a stack of full-width pills -------------------------- */
  SG.fit.register('.sheet__actions', { steps: ['row', 'stack'], parts: '.btn' });

  /* ---- Size: half <-> full ---------------------------------------------------------- */
  function setSize(sheet, size) {
    sheet.setAttribute('data-size', size);
    SG.qsa('[data-sg-sheet-size]', sheet).forEach(function (b) {
      b.setAttribute('aria-pressed', String(size === 'full'));
    });
  }

  var swallowClick = false;

  document.addEventListener('click', function (e) {
    var btn = e.target.closest ? e.target.closest('[data-sg-sheet-size]') : null;
    if (!btn) return;
    if (swallowClick) { swallowClick = false; e.preventDefault(); e.stopImmediatePropagation(); return; }
    var sheet = btn.closest('.sheet');
    if (!sheet) return;
    e.preventDefault();
    setSize(sheet, sheet.getAttribute('data-size') === 'full' ? 'half' : 'full');
  }, true);

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    var btn = e.target.closest ? e.target.closest('[data-sg-sheet-size]') : null;
    if (!btn) return;
    var sheet = btn.closest('.sheet');
    if (!sheet) return;
    e.preventDefault();
    setSize(sheet, e.key === 'ArrowUp' ? 'full' : 'half');
  });

  /* ---- Drag ---------------------------------------------------------------------------- */
  var drag = null;

  document.addEventListener('pointerdown', function (e) {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    var t = e.target;
    if (!t.closest) return;
    var grip = t.closest('.sheet__handle, .sheet .card__bar');
    if (!grip) return;
    // Buttons and fields on the bar keep their own behaviour; the handle is the drag grip.
    if (t.closest('.card__bar button, .card__bar a, .card__bar input, .card__bar select, .card__bar textarea, .card__bar label')) return;
    var sheet = grip.closest('.sheet');
    if (!sheet || sheet.hasAttribute('data-inline') || sheet.hasAttribute('data-required') || !isOpen(sheet) || isPanel(sheet)) return;
    drag = { sheet: sheet, grip: grip, id: e.pointerId, y0: e.clientY, dy: 0, moved: false, samples: [[e.clientY, e.timeStamp]] };
    try { grip.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointer */ }
  });

  document.addEventListener('pointermove', function (e) {
    if (!drag || e.pointerId !== drag.id) return;
    var dy = e.clientY - drag.y0;
    if (!drag.moved && Math.abs(dy) < SLOP) return;
    drag.moved = true;
    drag.dy = dy;
    drag.samples.push([e.clientY, e.timeStamp]);
    if (drag.samples.length > 6) drag.samples.shift();
    drag.sheet.setAttribute('data-dragging', '');
    drag.sheet.style.transform = 'translateY(' + Math.max(0, dy) + 'px)';
  });

  function endDrag(e, cancelled) {
    if (!drag || e.pointerId !== drag.id) return;
    var d = drag;
    drag = null;
    try { d.grip.releasePointerCapture(d.id); } catch (err) { /* already released */ }
    if (!d.moved) return;
    swallowClick = true;
    window.setTimeout(function () { swallowClick = false; }, 0);
    var sheet = d.sheet;
    var height = sheet.getBoundingClientRect().height || 1;
    var a = d.samples[0];
    var b = d.samples[d.samples.length - 1];
    var velocity = b[1] > a[1] ? (b[0] - a[0]) / (b[1] - a[1]) : 0; // px/ms, down is positive
    var dismiss = !cancelled && (d.dy > CLOSE_FRACTION * height || (velocity > FLICK && d.dy > 24));
    var reduced = SG.motion && SG.motion.reduced();

    if (dismiss && reduced) {
      // Stay where the finger left it and fade; the pose is reset once it is hidden.
      sheet.removeAttribute('data-dragging');
      SG.dialog.requestClose(sheet);
      if (isOpen(sheet)) sheet.style.transform = '';
      else settleLater(sheet);
      return;
    }
    // Clear the inline pose first: the transition then runs from where the finger left it.
    sheet.removeAttribute('data-dragging');
    sheet.style.transform = '';
    if (dismiss) SG.dialog.requestClose(sheet);
    else if (!cancelled && d.dy < -EXPAND_DRAG && sheet.getAttribute('data-size') !== 'full') setSize(sheet, 'full');
  }
  document.addEventListener('pointerup', function (e) { endDrag(e, false); });
  document.addEventListener('pointercancel', function (e) { endDrag(e, true); });

  function settleLater(sheet) {
    window.setTimeout(function () { if (!isOpen(sheet)) sheet.style.transform = ''; }, 500);
  }

  /* ---- Non-modal sheet: Esc, focus, scroll region -------------------------------------------- */
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape' || e.defaultPrevented) return;
    var sheet = e.target.closest ? e.target.closest('.sheet[popover]') : null;
    if (!sheet || !popoverOpen(sheet) || sheet.hasAttribute('data-required')) return;
    e.preventDefault();
    SG.dialog.close(sheet);
  });

  var watchers = typeof ResizeObserver === 'function' ? new WeakMap() : null;
  function publishSize(sheet) {
    var root = document.documentElement;
    var r = sheet.getBoundingClientRect();
    var panel = isPanel(sheet);
    root.style.setProperty('--sg-sheet-block', panel ? '0px' : Math.ceil(r.height) + 'px');
    root.style.setProperty('--sg-sheet-inline', panel ? Math.ceil(r.width) + 'px' : '0px');
  }
  function watchSize(sheet, on) {
    var root = document.documentElement;
    if (!on) {
      root.style.removeProperty('--sg-sheet-block');
      root.style.removeProperty('--sg-sheet-inline');
      if (watchers && watchers.has(sheet)) { watchers.get(sheet).disconnect(); watchers.delete(sheet); }
      return;
    }
    publishSize(sheet);
    if (watchers) {
      var ro = new ResizeObserver(function () { publishSize(sheet); });
      ro.observe(sheet);
      watchers.set(sheet, ro);
    }
  }

  document.addEventListener('toggle', function (e) {
    var sheet = e.target;
    if (!sheet.classList || !sheet.classList.contains('sheet') || !sheet.hasAttribute('popover')) return;
    if (e.newState === 'open') {
      SG.dialog.settle(sheet);
      watchSize(sheet, true);
    } else {
      watchSize(sheet, false);
      SG.dialog.restoreFocus(sheet);
      settleLater(sheet);
    }
  }, true);

  document.addEventListener('close', function (e) {
    if (e.target.classList && e.target.classList.contains('sheet')) settleLater(e.target);
  }, true);

  SG.sheet = {
    open: function (el, opts) { return SG.dialog.open(el, opts); },
    close: function (el, value) { return SG.dialog.close(el, value); },
    setSize: setSize,
  };
})((window.SG = window.SG || {}));
